import {ConfigurationDomainAdapter} from '../../../adapters/configuration/domain-adapter.js';
import {createConfigurationSurfaceComposition} from '../../../surfaces/configuration/composition.js';
import {describeContextProvider} from '../../../foundation/global/context-descriptor-contract.js';
const assert=(v    ,m='assertion failed')=>{if(!v)throw Error(m)};const run=(name       ,fn         ,out      )=>{try{fn();out.push({name,status:'PASS'})}catch(e){out.push({name,status:'FAIL',error:String((e       )?.message||e)})}};
const obs=(patch    ={})=>({key:'runtime.maxItems',presentVersion:'v7',redactedValue:'***12',source:'local-runtime-safe-config',observedAt:'2026-09-17T01:00:00Z',restartRequired:false,state:'AVAILABLE',...patch});
export function runConfigurationSurfaceTests(){const t      =[];
 run('configuration.empty-scope-is-explicit-not-all-config',()=>{const a=new ConfigurationDomainAdapter();assert(a.observeState().code==='EMPTY_SCOPE'&&a.rows().length===0)},t);
 run('configuration.observed-default-is-never-fabricated',()=>{const a=new ConfigurationDomainAdapter();assert(a.rows().length===0)},t);
 run('configuration.proposal-version-binds-observation',()=>{const a=new ConfigurationDomainAdapter({observations:[obs()]});a.select('runtime.maxItems');const p=a.beginProposal('runtime.maxItems','14');assert(p.baseVersion==='v7'&&p.state==='DRAFT')},t);
 run('configuration.validation-does-not-apply',()=>{const a=new ConfigurationDomainAdapter({observations:[obs()]});a.select('runtime.maxItems');a.beginProposal('runtime.maxItems','14');const p=a.validate();assert(p.state==='VALIDATED'&&p.application==='NOT_APPLIED')},t);
 run('configuration.authority-unavailable-stays-pending',()=>{const a=new ConfigurationDomainAdapter({observations:[obs()]});a.select('runtime.maxItems');a.beginProposal('runtime.maxItems','14');a.validate();const r=a.requestApply();assert(!r.ok&&r.code==='AUTHORITY_PENDING'&&r.proposal.application==='NOT_APPLIED')},t);
 run('configuration.explicit-authority-result-only-sets-applied',()=>{const a=new ConfigurationDomainAdapter({observations:[obs()],authority:{id:'authority-1',requestApply:()=>({status:'RESTART_REQUIRED',authorityId:'authority-1',appliedVersion:'v8'})}});a.select('runtime.maxItems');a.beginProposal('runtime.maxItems','14');a.validate();const r=a.requestApply();assert(r.ok&&r.code==='RESTART_REQUIRED'&&r.proposal.application==='RESTART_REQUIRED')},t);
 run('configuration.reset-discards-proposal-not-observation',()=>{const a=new ConfigurationDomainAdapter({observations:[obs()]});a.select('runtime.maxItems');a.beginProposal('runtime.maxItems','14');const r=a.reset();assert(r.ok&&r.observed==='***12'&&!a.proposal())},t);
 run('configuration.command-unavailable-emits-no-receipt',()=>{const c=createConfigurationSurfaceComposition();const before=c.commands.receipts.length;const r=c.commands.execute('configuration.requestApply',{});assert(r.ok===false&&c.commands.receipts.length===before)},t);
 run('configuration.collection-is-shared-core-bound-domain-data',()=>{const c=createConfigurationSurfaceComposition({adapter:new ConfigurationDomainAdapter({observations:[obs()]})});const s=c.collection.snapshot();assert(s.adapterId==='configuration.observations'&&s.totalRows===1&&c.slots.LEFT==='collection')},t);
 run('configuration.context-is-shared-descriptor-contract',()=>{const a=new ConfigurationDomainAdapter({observations:[obs()]});a.select('runtime.maxItems');const c=createConfigurationSurfaceComposition({adapter:a});const r=describeContextProvider(c.contextProvider,{key:'runtime.maxItems'});assert(r.ok&&r.descriptor.domainOwner==='ConfigurationDomainAdapter')},t);
 run('configuration.platform-truth-remains-unavailable-fallback',()=>{const c=createConfigurationSurfaceComposition();assert(c.platformTruth.activeKeyboardSource.includes('UNAVAILABLE')&&c.platformTruth.nativeWindow.includes('UNAVAILABLE'))},t);
 run('configuration.no-preference-config-collapse',()=>{const c=createConfigurationSurfaceComposition();assert(c.bottomProjection().providerTruth==='OPERATIONAL_CONFIG_AUTHORITY_UNAVAILABLE')},t);
 return t;}
if(import.meta.url===new URL(process.argv[1],'file:').href){const tests=runConfigurationSurfaceTests();console.log(JSON.stringify({surface:'configuration',pass:tests.filter(x=>x.status==='PASS').length,fail:tests.filter(x=>x.status==='FAIL').length,tests},null,2));if(tests.some(x=>x.status==='FAIL'))process.exitCode=1;}
